/* ───────── Tier 10 · motion and modern CSS ───────── */
const T10: Gen[] = [
  g('Transition', 'card', (r) => { const n = r.pick([150, 200, 250, 300, 400]), c = r.pick(HEX); return [`Make .btn change its background-color smoothly: transition: background-color ${n}ms ease, and on hover use ${c}.`, blk('.btn', `transition: background-color ${n}ms ease`) + '\n' + blk('.btn:hover', `background-color: ${c}`), 'Put the transition on the base state.', { state: true }]; }),
  g('Two transitions', 'card', (r) => { const n = r.pick([150, 200, 300]), y = r.int(2, 8); return [`Lift .btn on hover: transition: transform ${n}ms ease-out, box-shadow ${n}ms ease-out; on hover transform translateY(-${y}px) and box-shadow 0 8px 18px rgba(0, 0, 0, 0.3).`, blk('.btn', `transition: transform ${n}ms ease-out, box-shadow ${n}ms ease-out`) + '\n' + blk('.btn:hover', `transform: translateY(-${y}px)`, 'box-shadow: 0 8px 18px rgba(0, 0, 0, 0.3)'), 'Comma separate the transitions.', { state: true }]; }),
  g('Transition parts', 'card', (r) => { const d = r.pick([200, 300, 500]), w = r.pick([50, 100, 150]), o = r.pick([0.4, 0.5, 0.6]); return [`Fade .btn on hover with the long form: transition-property opacity, transition-duration ${d}ms, transition-delay ${w}ms; on hover opacity ${o}.`, blk('.btn', 'transition-property: opacity', `transition-duration: ${d}ms`, `transition-delay: ${w}ms`) + '\n' + blk('.btn:hover', `opacity: ${o}`), 'Three longhand transition properties.', { state: true }]; }),
  g('Keyframes fade', 'card', (r) => { const n = r.pick(['fade', 'appear', 'reveal']), d = r.pick([0.5, 0.8, 1, 1.5]); return [`Define @keyframes ${n} from opacity 0 to opacity 1, and run it on .card for ${d}s with ease-out.`, `@keyframes ${n} {\n  from { opacity: 0; }\n  to { opacity: 1; }\n}\n` + blk('.card', `animation: ${n} ${d}s ease-out`), 'Name the keyframes, then reference the name.']; }),
  g('Spinner', 'card', (r) => { const d = r.pick([1, 2, 3]); return [`Spin .badge forever: display inline-block, an @keyframes spin that ends at rotate(360deg), animation spin ${d}s linear infinite.`, `@keyframes spin {\n  to { transform: rotate(360deg); }\n}\n` + blk('.badge', 'display: inline-block', `animation: spin ${d}s linear infinite`), 'Only a "to" frame is needed.']; }),
  g('Pulse', 'card', (r) => { const s = r.pick([1.1, 1.15, 1.2]), d = r.pick([1, 1.5, 2]); return [`Pulse .btn: @keyframes pulse with a 50% frame at transform scale(${s}), animation pulse ${d}s ease-in-out infinite.`, `@keyframes pulse {\n  50% { transform: scale(${s}); }\n}\n` + blk('.btn', `animation: pulse ${d}s ease-in-out infinite`), 'A single middle frame is enough.']; }),
  g('Alternate', 'card', (r) => { const n = r.int(20, 80), d = r.pick([1, 2]); return [`Slide .badge sideways and back: display inline-block; @keyframes slide from translateX(0) to translateX(${n}px); animation slide ${d}s ease-in-out infinite alternate.`, `@keyframes slide {\n  from { transform: translateX(0); }\n  to { transform: translateX(${n}px); }\n}\n` + blk('.badge', 'display: inline-block', `animation: slide ${d}s ease-in-out infinite alternate`), 'alternate plays forwards then backwards.']; }),
  g('Delay and fill', 'card', (r) => { const d = r.pick([400, 600, 800]), w = r.pick([100, 200, 300]); return [`Fade .title in with a delay: @keyframes fade from opacity 0 to 1; animation fade ${d}ms ease-out ${w}ms both.`, `@keyframes fade {\n  from { opacity: 0; }\n  to { opacity: 1; }\n}\n` + blk('.title', `animation: fade ${d}ms ease-out ${w}ms both`), 'both applies the first and last frame.']; }),
  g('Steps', 'card', (r) => { const d = r.pick([1, 2]); return [`Blink .badge: @keyframes blink with a 50% frame at opacity 0, animation blink ${d}s steps(1) infinite.`, `@keyframes blink {\n  50% { opacity: 0; }\n}\n` + blk('.badge', `animation: blink ${d}s steps(1) infinite`), 'steps(1) jumps instead of easing.']; }),
  g('Glow', 'card', (r) => { const c = r.pick(HEX), n = r.int(12, 28); return [`Make .btn glow: @keyframes glow with 0% box-shadow 0 0 0 ${c}, 50% box-shadow 0 0 ${n}px ${c}, 100% box-shadow 0 0 0 ${c}; animation glow 2s ease-in-out infinite.`, `@keyframes glow {\n  0% { box-shadow: 0 0 0 ${c}; }\n  50% { box-shadow: 0 0 ${n}px ${c}; }\n  100% { box-shadow: 0 0 0 ${c}; }\n}\n` + blk('.btn', 'animation: glow 2s ease-in-out infinite'), 'Three keyframes in a loop.']; }),
  g('Scroll snap', 'sticky', (r) => { const a = r.pick(['start', 'center']), ax = r.pick(['y', 'x']); return [`Snap the scroller: .scroller gets scroll-snap-type ${ax} mandatory, and every .scroller p gets scroll-snap-align ${a}.`, blk('.scroller', `scroll-snap-type: ${ax} mandatory`) + '\n' + blk('.scroller p', `scroll-snap-align: ${a}`), 'The container snaps, the children are snap points.']; }),
  g('Cascade layers', 'card', (r) => { const [a, b] = r.two(HEX); return [`Declare @layer base, theme; put .title color ${a} in the base layer and .title color ${b} in the theme layer. Theme is declared last, so ${b} must win.`, `@layer base, theme;\n@layer base {\n  .title { color: ${a}; }\n}\n@layer theme {\n  .title { color: ${b}; }\n}`, 'Later layers beat earlier layers.']; }),
  g('Supports', 'boxes', (r) => { const n = r.int(6, 20); return [`Wrap a grid layout in a feature query: @supports (display: grid) { .row { display: grid; gap: ${n}px } }.`, `@supports (display: grid) {\n  .row {\n    display: grid;\n    gap: ${n}px;\n  }\n}`, '@supports checks browser support.']; }),
  g('Nesting', 'card', (r) => { const n = r.int(12, 32), c = r.pick(HEX); return [`Use CSS nesting: .card { padding ${n}px; and a nested .title with color ${c} }.`, `.card {\n  padding: ${n}px;\n  .title {\n    color: ${c};\n  }\n}`, 'Nested rules live inside the parent block.']; }),
  g('Nested hover', 'card', (r) => { const c = r.pick(HEX); return [`Use CSS nesting for hover: .btn { background-color: ${c}; and a nested &:hover with opacity 0.8 }.`, `.btn {\n  background-color: ${c};\n  &:hover {\n    opacity: 0.8;\n  }\n}`, '& stands for the parent selector.', { state: true }]; }),
  g('Counters', 'list', (r) => { const c = r.pick(HEX); return [`Number the list with counters: .list gets counter-reset item, list-style none, padding 0; .item gets counter-increment item; .item::before shows content counter(item) ". " in ${c}.`, blk('.list', 'counter-reset: item', 'list-style: none', 'padding: 0') + '\n' + blk('.item', 'counter-increment: item') + '\n' + blk('.item::before', 'content: counter(item) ". "', `color: ${c}`), 'counter-reset, counter-increment, counter().']; }),
  g('3D tilt', 'card', (r) => { const p = r.pick([400, 600, 800]), a = r.pick([-20, -10, 10, 20]); return [`Tilt .card in 3D: transform perspective(${p}px) rotateY(${a}deg).`, blk('.card', `transform: perspective(${p}px) rotateY(${a}deg)`), 'perspective() goes first in the list.']; }),
  g('Focus within', 'form', (r) => { const c = r.pick(HEX); return [`Highlight the whole form while any field inside has focus: .form:focus-within gets an outline of 2px solid ${c}.`, blk('.form:focus-within', `outline: 2px solid ${c}`), ':focus-within matches parents of the focused element.', { state: true }]; }),
  g('Focus visible', 'card', (r) => { const c = r.pick(HEX), o = r.int(2, 6); return [`Give .btn a keyboard focus ring: .btn:focus-visible gets outline 3px solid ${c} and outline-offset ${o}px.`, blk('.btn:focus-visible', `outline: 3px solid ${c}`, `outline-offset: ${o}px`), ':focus-visible only shows for keyboard focus.', { state: true }]; }),
];

const TIERS: Gen[][] = [T1, T2, T3, T4, T5, T6, T7, T8, T9, T10];
export const FAMILY_COUNT = TIERS.reduce((n, t) => n + t.length, 0);

const ADJ = ['Gilded', 'Rosy', 'Polar', 'Soft', 'Drifting', 'Amber', 'Frosted', 'Luminous', 'Velvet', 'Northern', 'Quiet', 'Glowing', 'Hazy', 'Opal', 'Distant', 'Coral', 'Silken', 'Crystal', 'Warm', 'Boreal', 'Pale', 'Ember', 'Shimmering', 'Wide', 'Tidal', 'Misty', 'Golden', 'Floating', 'Slow', 'Bright', 'Winter', 'Painted', 'Hushed', 'Radiant', 'Honeyed'];
const NOUN = ['Ribbon', 'Curtain', 'Horizon', 'Canvas', 'Prism', 'Halo', 'Gradient', 'Meadow', 'Lantern', 'Glacier', 'Shimmer', 'Veil', 'Kite', 'Beacon', 'Aurora', 'Compass', 'Thread', 'Window', 'Ember', 'Lagoon', 'Feather', 'Mirror', 'Orbit', 'Garden', 'Signal', 'Bridge', 'Harbor', 'Atlas'];
export const titleFor = (i: number) => { const a = i % ADJ.length; return `${ADJ[a]} ${NOUN[(Math.floor(i / ADJ.length) + a) % NOUN.length]}`; };

/** Builds levels `from` to `to` (inclusive). Guarantees unique prompts and answers of 20 lines or fewer. */
export function buildLevels(from: number, to: number, seen: Set<string> = new Set()): Array<Built & { id: number; tier: number }> {
  const out: Array<Built & { id: number; tier: number }> = [];
  const span = to - from + 1, perTier = Math.ceil(span / 10);
  for (let id = from; id <= to; id++) {
    const idx = id - from, tier = Math.min(10, Math.floor(idx / perTier) + 1), j = idx - (tier - 1) * perTier, fams = TIERS[tier - 1];
    const cycle = Math.floor(j / fams.length), order = fams.map((_, k) => k).sort((x, y) => ((x * 2654435761 + cycle * 40503 + tier) % 997) - ((y * 2654435761 + cycle * 40503 + tier) % 997));
    let made: Built | null = null;
    for (let attempt = 0; attempt < 400 && !made; attempt++) {
      const fam = fams[order[(j + Math.floor(attempt / 100)) % fams.length]];
      const cand = fam(rng(id * 7919 + attempt * 104729 + tier));
      if (!seen.has(cand.prompt) && cand.target.split('\n').length <= 20) made = cand;
    }
    if (!made) throw new Error(`Could not build a unique level ${id}`);
    seen.add(made.prompt);
    out.push({ ...made, id, tier });
  }
  return out;
}
